export const DESCRIPTIONS: Record<string, string> = {
  "t60": "Una charla para ejecutivos enfocada en cómo hacer que su empresa sea parte de las respuestas de la IA.",
  "t61": "Esta especialista de AWS, analiza cómo aplicar a la IA para que aporte a la rentabilidad corporativa.",
  "t203": "Las redes sociales rompieron el monopolio de los medios y la IA ahora puede redactar, editar y hasta inventar una noticia en segundos. ¿Qué queda del periodismo cuando cualquiera publica y nada garantiza que algo sea verdad? Periodistas, tecnólogos y creadores de contenido debaten cómo se verifica la información y quién se gana la confianza del público.",
  "t63": "Towerbank e Ikigii explican el nuevo escenario Boliviano y la estrategia que llevó a TOYOTA a sumarse al mundo Crypto.",
  "t65": "En 2024 el mercado pagaba más de tres dólares por cada dólar de bitcoin en el balance de Strategy. Hoy paga menos de uno. Alguien levantó capital contra esa prima y alguien la compró arriba.",
  "t66": "Casos reales de litigios y causas penales en el ecosistema crypto global y regional, para entender cómo piensan jueces y fiscales frente a Web3, y cómo un founder o inversor puede anticipar y mitigar su exposición legal.",
  "t67": "Expandirse a Latinoamérica no es traducir una web ni contratar un vendedor regional. Es elegir mercados, partners, pricing, estructura comercial y operación local. Un playbook práctico para compañías B2B que quieran entrar a la región sin tratarla como si fuera un único mercado.",
  "t149": "¿Y si el futuro de la banca no fuera una aplicación, sino una inteligencia artificial que maneja tu dinero por vos?\n\nEstamos pasando de usar aplicaciones financieras a tener agentes de IA capaces de realizar pagos, administrar fondos, buscar rendimientos y ejecutar operaciones en nuestro nombre.\n\nUna charla sobre el nacimiento de la banca agéntica, una nueva generación de servicios financieros donde las personas definen objetivos y reglas, mientras las máquinas se encargan de ejecutarlos.\n\n¿Qué rol jugarán Bitcoin, las stablecoins y las finanzas tradicionales? ¿Cómo se garantiza la seguridad? ¿Y hasta dónde estamos dispuestos a delegar el control de nuestro dinero?\n\nSi el futuro es que tu dinero trabaje solo, la gran pregunta es: ¿quién tendrá realmente el control?",
  "t146": "How can you get more out of your mining equipment?\n\nA practical talk on using firmware to fine-tune power consumption, hashrate, and temperature to improve ASIC efficiency. Learn when to boost hashrate, when to reduce power consumption, and how to assess whether a configuration truly improves profitability, accounting for electricity costs, firmware fees, and operational stability.",
  "t138": "Los creadores de LABITCONF dan la bienvenida a este nuevo evento, y nos orientan sobre como aprovechar al máximo todas las charlas.",
  "t1": "Cuando todo el interés parece haber migrado hacia la IA, hacia los stablecoins, o la tokenización, esta charla nos explica porqué Bitcoin sigue siendo el activo más importante en un futuro donde la IA y otras tecnologías promueven la abundancia.",
  "t137": "Desde hoy, La Argentina cuenta con su propio Monumento a Satoshi Nakamoto y a su Creación. A través de éste corto Documental presentaremos el trabajo y los significados que encierra este flamante monumento a Satoshi Nakamoto inaugurado en el Polo Tecnológico DOT.",
  "t3": "The author of the #1 book in Bitcoin \"The Bitcoin Standard\", explains what he has learned in the eight years since the book came out, which predictions aged well and which didn't, and how he sees Bitcoin in a world of inflation, debt and the digital dollar.",
  "t4": "Cómo cambian las estrategias de inversión cuando los movimientos en los mercados y las acciones se miden y operan en Bitcoin.",
  "t5": "The creator of \"The Power Law\" model, explains why Bitcoin's price seems to have followed a power law for fifteen years, what that says about adoption as a physical rather than a financial phenomenon, and what the model projects for the coming cycles. Accessible math.",
  "t6": "Uno de los mayores tecnocratas locales cuenta sobre su largo camino explorando de las fronteras tecnológicas cruzando crypto, inteligencia artificial, comunicación e identidad.",
  "t7": "¿Y si la mayor riqueza de Bitcoin no fuera su precio, sino el privilegio de haber descubierto una herramienta de libertad antes que la mayoría?\n\nUna reflexión sobre responsabilidad, legado y cómo transformar la abundancia en comunidades más libres, resilientes y humanas.",
  "t8": "​La filosofía Solarpunk proyecta un futuro donde tecnología y naturaleza prosperan en armonía. Para superar el extractivismo y alcanzar el Nivel 1 de Kardashev, necesitamos un patrón monetario libre: Bitcoin es el motor soberano para financiar una Civilización Regenerativa distribuida.",
  "t9": "Los mayores especialistas latinos en autocustodia reflexionan ¿por qué importa controlar tus propias llaves y qué desafíos implica?\n\nUn panel sobre seguridad, herramientas, errores frecuentes y herencia, para entender cómo dar el paso hacia la autocustodia y sostenerla en el tiempo.\n\nPorque HODL también es aprender a cuidar lo que decidís conservar.",
  "t139": "Una reflexión sobre el rol de LABITCONF y la Fundación Bitcoin Iberoamérica durante sus 14 años de trayectoria y qué sigue hacia delante.",
  "t10": "Los principales lideres del análisis técnico, fundamental y On-Chain se juntan para reflexionar sobre el precio futuro de Bitcoin.",
  "t11": "Cuatro sobrevivientes a las dictaduras de Cuba y Venezuela con cuentan cómo se usa y qué función cumple Bitcoin cuando el sistema financiero te cierra la puerta: sanciones, bloqueos, controles de cambio y falta de bancos.\n\nHistorias reales de adopción donde Bitcoin no es inversión sino un salvavidas.",
  "t12": "Cinco voces de terreno (Bolivia, El Salvador, Brasil, Costa Rica y Ecuador) sobre qué está impulsando de verdad la adopción de Bitcoin en la región: crisis, comunidades, educación, cajeros y comercio.\n\nQué se repite en todos los países y qué es propio de cada uno.",
  "t13": "Cómo se mina Bitcoin fuera de la red eléctrica, con energía que de otro modo se desperdicia. Desde el gas de venteo hasta la biodigestión de basura,\n\n¿Son rentable estos proyecto en la región?.",
  "t15": "More and more companies are adding bitcoin to their balance sheets, and a whole new category of companies was born just to accumulate it. Is it a sound financial strategy or leverage that ends badly? This panel looks at it from every angle: an operating company that actually uses BTC, the valuation models behind the thesis, the OTC desk that executes the purchases, and a critical journalistic take on the treasury boom.",
  "t16": "Argentina is an open-air monetary laboratory. After decades of inflation, Javier Milei's government promised to end it: zero deficit, no more money printing, and a path toward currency competition.\n\nSaifedean Ammous, author of The Bitcoin Standard, debates the argentine economist Iván Carrino. Austrian theory vs the country's actual experience.\n\nAre the reforms heading in the right direction or stopping halfway? Is there a path to Sound Money for Argentina today? Where are we and at what cost?",
  "t17": "Maximiliano Firtman repasa dónde está hoy la inteligencia artificial y qué tan cerca (o lejos) estamos de una Inteligencia General (AGI) y de una Super Inteligencia (ASI): qué significan esos términos, qué señales concretas hay en los modelos actuales, qué falta, y qué podría cambiar en el trabajo, la economía y el poder si llegamos.",
  "t18": "Durante siglos la inteligencia fue el recurso más escaso del ser humano; hoy la IA da acceso en segundos a análisis, creatividad y ejecución que antes exigían años. ¿Qué pasa con el ser humano cuando la inteligencia deja de ser su principal ventaja?\n\nLa respuesta está en lo que la tecnología no resuelve: propósito, criterio, identidad, valores y conciencia.\n\nSØD es un experimento para usar IA no solo para producir más, sino para acompañar autoconocimiento, claridad y acción.",
  "t19": "Una abogada y un desarrollador cruzan dos preguntas del momento: cómo se identifica técnicamente a un agente de IA que ya tiene wallet y opera solo, y quién responde legalmente por lo que hace.",
  "t20": "Los defensores de la propiedad intelectual argumentan que sin la misma no habría avances tecnologicos relevantes por lo que ellos consideran una falta de incentivos para recuperar las inversiones necesarias.\n\nLos negadores de la existencia de la propiedad intelectual manifiestan que la misma es una aberración jurídca contra natura surgida del capricho de gente violenta y autoritaria ocupando espacios formales de poder.\n\nUn interesante debate entre las partes.",
  "t21": "La IA generativa plantea un nuevo desafío: hacer programable la propiedad intelectual. Esta charla presenta las Seeds, una propuesta para convertir cualquier creación en una unidad programable que integra derechos, licencias, regalías y trazabilidad para personas, empresas y agentes de IA.",
  "t22": "Mientras la discusión pública seguía atada a la pregunta de si la inteligencia artificial iba a matar la música, ocurrió algo menos vistoso y más profundo: la IA dejó de ser una herramienta que alguien elige abrir y pasó a funcionar como infraestructura.",
  "t23": "Cómo la inteligencia artificial puede transformar al Estado en una organización más eficiente, más transparente y más barata, y además construir herramientas para potenciar al ciudadano.",
  "t24": "Un panel sobre cómo la inteligencia artificial está cambiando la universidad: qué se enseña, cómo se evalúa y qué rol le queda al docente cuando el alumno tiene un modelo que responde todo.",
  "t25": "¿Estamos frente a una revolución en la propiedad y el intercambio de activos o simplemente poniendo nuevos nombres a viejos negocios?\n\nDesde inmuebles y energía hasta instrumentos financieros, la tokenización promete democratizar inversiones, generar liquidez y transformar la manera en que representamos y transferimos valor.\n\nPero ¿qué está funcionando realmente? ¿Qué cambia cuando un activo se convierte en un token? ¿La tecnología elimina intermediarios o simplemente los reemplaza? ¿Y qué falta para que la tokenización alcance una adopción masiva?\n\nCompartiremos experiencias concretas, desafíos regulatorios y oportunidades de negocio para separar las aplicaciones reales del entusiasmo tecnológico.\n\nPorque tokenizar un activo es relativamente fácil. Lo difícil es lograr que ese token tenga valor, derechos exigibles, compradores y un mercado real.",
  "t14": "Graeme Moore (Project Eleven) on the quantum threat to Bitcoin: what a quantum computer can and can't break, how far off it is given the advances of 2026, what BIP-360 proposes, and what a holder should do today. FUD, or a reality just around the corner?",
  "t27": "Las finanzas descentralizadas prometen operar sin intermediarios, mientras que la banca tradicional necesita identificar clientes, cumplir regulaciones y administrar riesgos. ¿Son dos mundos incompatibles?\n\nStablecoins, swaps, préstamos y liquidaciones on-chain ofrecen oportunidades para transformar los servicios financieros. Pero ¿cómo incorporar estas innovaciones sin perder sus ventajas ni comprometer las obligaciones regulatorias?\n\nDesde DeFi, la banca y la regulación, tres perspectivas para debatir qué puede aprender cada mundo del otro, dónde pueden complementarse y qué barreras todavía los separan.\n\n*¿Puede la banca adoptar lo mejor de DeFi sin quitarle aquello que la hace diferente?*",
  "t28": "Que hay de los exchanges con la compresión de los márgenes, la competencia y las nuevas regulaciones? Alcanza solo con cripto? Que pasa con las stablecoins locales y los pagos agénticos? Que quieren los nuevos usuarios en América Latina?",
  "t45": "Charla introductoria de Workshop + Coders sobre qué hay realmente detrás de la IA generativa: cómo se entrena un modelo, qué es un token, por qué a veces \"alucina\" y qué puede y no puede hacer. Pensada para quien usa ChatGPT o similares todos los días pero nunca vio cómo funcionan por dentro.",
  "t46": "Taller práctico y oficial de OpenAI Codex a cargo de Maximiliano Firtman: cómo construir agentes de IA que ejecutan tareas reales (leer código, escribir, automatizar flujos) con las herramientas de OpenAI. Los asistentes reciben créditos para usar la plataforma durante y después del taller. Traé notebook.",
  "t48": "Taller introductorio y práctico sobre finanzas descentralizadas con Bitcoin. Exploraremos Rootstock, billeteras, stablecoins, exchanges y préstamos para aprender a operar sin intermediarios y conservar la custodia de los fondos.",
  "t49": "En este Workshop aprenderás cómo funcionan las técnicas de privacidad on-chain: PayJoin, CoinJoin, silent payments y otras formas de romper la trazabilidad de tus transacciones. Qué protege cada una, qué no, y cómo usarlas hoy.",
  "t50": "Exploraremos técnicas prácticas para recuperar seeds y passphrases mal escritas u olvidadas: corrección por typos, ataques dirigidos y wordlists, herramientas de recuperación y forenses, compatibilidad de wallets, ejemplos reales y límites legales.",
  "t51": "Se analizará el tratamiento tributario de las principales operaciones en las finanzas descentralizadas, como staking, préstamos, provisión de liquidez e intercambios de criptoactivos. Se abordarán los criterios aplicables en los principales impuestos, tanto en Argentina como a nivel mundial",
  "t52": "Framework legal, tributario y regulatorio para lanzar productos Bitcoin y Crypto desde Argentina en 2026: qué jurisdicción elegir, cómo estructurar la empresa y qué errores evitar frente a inversores globales.",
  "t53": "En este taller práctico se abordará el desarrollo de un contrato inteligente en Ethereum orientado a transferencias de fondos peer-to-peer (P2P), sirviendo como puerta de entrada al ecosistema Web3. Los asistentes aprenderán desde cero la sintaxis y lógica elemental de Solidity, utilizando Remix IDE",
  "t54": "A través de proyectos reales, exploraremos cómo usar vibe coding para crear wallets autocustodiadas, APIs que cobran en sats y agentes de IA que pagan y consumen servicios de forma autónoma. Qué acelera la IA, dónde falla y por qué la autocustodia es clave para construir la economía agéntica sobre Bitcoin.",
  "t55": "La próxima generación de Internet estará impulsada por agentes y máquinas que intercambian valor de forma autónoma. Bit2 propone una nueva Layer 2 sobre Bitcoin, basada en client-side validation, para pagos instantáneos, privados, determinísticos y de alto throughput.",
  "t56": "Stablecoins dominate crypto in Latin America, yet none offer real privacy. This talk shows how RGB Protocol on Bitcoin enables private, self-custodial stablecoins through private contracts validated client-side, and what USDT arriving natively on Bitcoin means for the region.",
  "t59": "Bitcoin está pensado para el largo plazo, pero HODLear no alcanza si no resolvemos continuidad, herencia y acceso futuro. Esta charla muestra cómo las Capas 2 y smart contracts sobre Bitcoin habilitan casos reales, tomando a BΔLT como ejemplo.",
  "t57": "Un agente puede probar cientos de estrategias en minutos, pero también multiplicar el sobreajuste. En una demo veremos: hipótesis, datos, reglas, costos, backtest, validación fuera de muestra y reporte. El objetivo no es buscar ganancias mágicas, sino descartar ideas débiles con mayor velocidad.",
  "t58": "Explora el impacto cognitivo de la volatilidad, la psicología detrás del HODL y cómo dominar tus emociones para tomar decisiones.",
  "t141": "Bitcoin Argentina lleva 13 años explicando Bitcoina en todo el país y siendo el principal bocero en los medios. Acercate a conocer qué puede hacer por vos.",
  "t29": "Niños, adolescentes y adultos mayores no son solo tres públicos distintos para enseñar una tecnología: son el espejo de cómo el propio Bitcoin madura con el tiempo. Y las tres etapas terminan enseñando lo mismo que Bitcoin — que no hay atajos, solo tiempo bien invertido.",
  "t31": "Al cabo de la charla, los participantes serán capaces de responder si Bitcoin es legal en Argentina, qué sabe el Estado y si hay que pagar impuestos.",
  "t32": "La frase \"¿para qué si no tengo nada que ocultar?\" nos hizo bajar la guardia en un mundo que cada vez más la necesita. Charlemos por qué la privacidad importa y cómo podemos empezar a hacerla valer de forma práctica.\nHODL tus datos.",
  "t33": "Cada bitcoin tiene una historia. ¿Sabés de dónde vienen los tuyos? En este taller práctico, pensado para quienes quieran iniciarse en trazabilidad sin conocimientos técnicos previos, aprenderemos a seguir el rastro de una transacción y descubrir qué puede contarnos sobre su pasado.",
  "t34": "¿Qué ocurre con tus bitcoin si mañana no estás? Esta charla explora cómo diseñar planes de herencia seguros para personas, familias y empresas, utilizando herramientas como multifirma, timelocks y passphrases para asegurar la continuidad del patrimonio sin perder la soberanía.",
  "t35": "Analizaremos la continuidad patrimonial para entender cómo pasar de la tenencia, trazabilidad y control tecnológico de los activos a la atribución jurídica, vinculando activos con personas y derechos, y diferenciando la capacidad de disponer mediante claves privadas de la legitimación legal para hacerlo.",
  "t36": "El Latin America Bitcoin Impact Fund (LABIF) acelera el ecosistema Bitcoin en Latinamérica financiando iniciativas de alto impacto. Presentaremos nuestro modelo en Geyser, criterios de evaluación, transparencia presupuestaria y resultados medibles del impacto en Bitcoin. geyser.fund/labif",
  "t37": "Los autores del Libro Economías Circularers y el creadores de la 1er economía circular de El Salvador compaten su experiencia en El Zonte, África y Sudamérica, qué funciona y qué no al construir una economía circular de Bitcoin: comercios, educación, cobros en sats y la comunidad como base. Formato conversación con consejos concretos.",
  "t40": "El #RetoBitcoin365 convirtió el hábito de comprar sats cada día en una comunidad de educación y adopción. Esta charla presenta su Modelo de Adopción Progresiva y la ruta para llevar el aprendizaje, la autocustodia y el uso de Bitcoin hacia una economía circular en un territorio.",
  "t38": "Aprende qué es Cashu y cómo funciona el dinero electrónico ecash sobre Bitcoin. En este taller exploraremos su modelo de privacidad, cómo crear y recibir tokens, realizar pagos y utilizar una mint, y qué ventajas y limitaciones tiene frente a otros sistemas de Bitcoin.",
  "t30": "¿Reconocerías una estafa cripto antes de caer? Aprendé cómo operan los ataques que vacían billeteras todos los días y llevate consejos prácticos para proteger tus fondos.",
  "t42": "Bitcoin suele explicarse desde conferencias, podcasts y conceptos técnicos. ¿Qué pasa cuando hay que explicarlo a gente de afuera del ecosistema? Jerónimo Ferrer creó un Bitcoin Walking Tour: un recorrido por la ciudad que usa lugares y situaciones cotidianas para explicar dinero, inflación, escasez, autocustodia y pagos, sin conocimientos previos. Cómo surgió, cómo diseñó la experiencia, qué preguntas aparecen cuando Bitcoin sale de su ambiente y qué aprendió enseñándolo distinto.",
  "t43": "Entrevista a Tomi Cristal, presentado como el inversor más joven de Argentina: cómo empezó, qué aprendió, cómo ve Bitcoin y las finanzas su generación.",
  "t44": "Entrega de premios del concurso del IFEB, con Gabriel Kurman: presentación de los proyectos ganadores de impacto con Bitcoin en Latinoamérica.",
  "t70": "Espacio abierto de consultas en el espacio BitcoinAR: especialistas de Bitcoin Argentina y del ecosistema responden en vivo, en grupos chicos, las dudas que la gente trae sobre Bitcoin y criptomonedas: cómo comprar, cómo guardar, qué es una seed, qué pasa con los impuestos. Sin agenda fija: se pregunta lo que se quiera.",
  "t178": "Conocé como brindarles herramientas gratuitas a tus estudiantes",
  "t198": "Panel de periodistas sobre las complejidades y responsabilidades de cubrir industrias que cambian a gran velocidad, con fuerte carga técnica, intereses económicos y riesgo de amplificar hype, proyectos dudosos o estafas. Una conversación sobre rigor, verificación y criterio editorial.",
  "t142": "La Passphrase BIP39 suma una capa adicional de seguridad a la frase semilla, permitiendo crear billeteras independientes a partir del mismo respaldo.\n\nEn esta charla aprenderás cuándo utilizarla, sus beneficios, riesgos con las mejores prácticas para implementarla correctamente.",
  "t157": "Qué ocurre cuando recibimos USDT/USDC vinculados a fondos ilícitos sin saberlo, incluso cuando nuestros propios fondos están almacenados en una hardware wallet.\n\nEsta charla explora el mundo de las stablecoins frizadas por intervención estatal sin intervención del usuario y las diferencias con Bitcoin.",
  "t160": "El equipo de la Clinica de Legales de la ONG Bitcoin Argentina, junto a un respoansable de la División Ciberdelitos de la Policía de la Ciudad, van a responder las consultas legales en vivo.",
  "t190": "Espacio de preguntas sobre aspectos contables e impositivos",
  "t173": "Veni a conocer 10 tips de lo que deberias presentar a tu contador",
  "t172": "Aprendè todo lo que necesites para no perder tus BTC con una capa adicional de seguridad",
  "t163": "Una charla sencilla que recorre las diferentes estrategas para comprar o cobrar por bitcoins tanto en forma privada como mediante medios más formales,",
  "t179": "Los chicos tienen una virtud que muchos adultos perdimos: preguntan sin miedo a parecer ignorantes.\n\nEn esta charla exploraremos esas preguntas simples, incómodas y a veces sorprendentes que nos obligan a repensar lo que creemos saber sobre Bitcoin, el dinero y su funcionamiento.\n\nPorque a veces las preguntas más inocentes son las más difíciles de responder.",
  "t187": "Arma tu frase semilla en tu casa, simplemente con un dado",
  "t156": "El creador de Bitcoin Stratos, un proyecto argentino que busca llevar Bitcoin a nuevas alturas, nos invita a descubrir las formas más ingeniosas y sorprendentes de mantener la red funcionando frente a la censura, los bloqueos y las interrupciones de conectividad.\n\nUn recorrido por proyectos reales, experimentos extraordinarios y desafíos tecnológicos: desde transacciones transmitidas por radio y servicios que funcionan sin datos móviles hasta satélites y globos estratosféricos.",
  "t186": "¿Qué hace que algo sea buen dinero? ¿Qué tienen en común Bitcoin, el oro y el dólar, y en qué se diferencian?\n\nUna ronda abierta para comparar sus propiedades: escasez, durabilidad, divisibilidad, portabilidad, verificabilidad, resistencia a la censura y capacidad de preservar valor.\n\nUn debate participativo donde los argumentos importan más que las certezas y el público también tiene la palabra.\n\n¿Cuál está mejor preparado para el futuro del dinero?",
  "t161": "Conversación sobre qué es la Bitcoineta y su trayectoria",
  "t205": "Demostrá que sos el que más sabe sobre Bitcoin y llevate premios!!\n\nParticipá de los Kahoots de Bitcoin.AR junto a La Bitcoineta. Respondé bien y rápido a las preguntas que aparecen en pantalla y ganate increibles premios.",
  "t164": "En esta charla reflexionamos sobre el rol de los nodos en Bitcoin, vemos una corriendo e vivo y analizamos las ventajas que nos ofrece operar el propio.",
  "t183": "Desde la Bitcoineta exploramos como leer y aprovechar la mempool y te ecplicamos como funcionan los fees.\n\nTe damos además algunos consejos para tips que te pueden ahorrar sats en tus transacciones futuras.",
  "t170": "Demostrá que sos el que más sabe sobre Bitcoin y llevate premios!!\n\nParticipá de los Kahoots de Bitcoin.AR junto a La Bitcoineta. Respondé bien y rápido a las preguntas que aparecen en pantalla y ganate increibles premios.",
  "t204": "Un torneo en vivo, con palabras bitcoiners y que se juega desde el celular.\n\nArrancan 64 jugadores y en cada bloque queda la mitad, como un halving, hasta que dos se cruzan en la final descifrando una frase de Satoshi.\n\nHay ahorcado, anagramas, sopa de letras, acrósticos, semillas BIP39 y criptogramas: velocidad, memoria y cultura cypherpunk.\n\nEl pozo se arma con aportes voluntarios en sats por Lightning.",
  "t128": "LATAM pasó del vacío regulatorio cripto a un patchwork de normas distintas: Argentina sin marco stablecoin propio, Brasil con licencias exigibles antes de octubre 2026, Colombia y Uruguay con sandboxes. Un mapa comparado y una secuencia práctica para entrar a la región sin fricción regulatoria.",
  "t129": "Estrategias legales para levantar capital en proyectos Bitcoin y Crypto: SAFEs, SAFTs, grants, rondas seed y Serie A, hasta la salida a IPO. Qué instrumento usar en cada etapa y qué errores evitar frente a inversores.",
  "t130": "¿Es legal apostar dinero sobre el resultado de una elección, un evento deportivo o una decisión económica? ¿Estamos frente a una nueva herramienta financiera o una forma sofisticada de apuestas?\n\nLos mercados de predicción desafían las categorías regulatorias tradicionales. Una charla para explorar su encuadre legal en Argentina, los riesgos para plataformas y usuarios, y los desafíos de regular una industria que combina información, especulación y tecnología.",
  "t62": "A face-to-face conversation with Saifedean Ammous on the Business stage (VIP area): an intimate interview format for Saturday's audience. A walk through Bitcoin as an individual and a corporate store of value, history, dollar, debt.",
  "t143": "Can Bitcoin’s Power Law help companies build smarter long-term strategies?\n\nGiovanni Santostasi and Alfredo Roisenzvit explore how this mathematical model can inform corporate Bitcoin treasuries, capital allocation, risk management, and financial planning.\n\nFrom price projections to real business decisions: how can companies use the Power Law to think strategically about Bitcoin, without confusing a mathematical model with a guarantee of future returns?",
  "t147": "Muchas startups dejan lo legal para después, pero algunas decisiones tempranas pueden generar problemas cuando llega el momento de escalar, sumar equipo o levantar inversión. La charla propone un recorrido práctico por los principales puntos que un founder debería ordenar desde el inicio: acuerdos entre socios, propiedad intelectual, contratos, contratación de talento, protección de datos, cap table, inversión y, cuando corresponda, regulación aplicable a productos tech o Web3.",
  "t68": "PlataMT es, en términos simples, un traductor automático entrenado específicamente para cripto y para Argentina. Aprende terminología de exchanges, voseo y criterios CNV-aware. La charla muestra por qué una traducción correcta puede no ser adecuada para el mercado local.",
  "t69": "¿Cómo garantizar que un ticket sea auténtico, verificable y trazable? Conoceremos cómo Hallos utiliza Blockchain como capa de confianza para transformar la emisión, propiedad, transferencia y reventa de entradas.",
  "t71": "¿Como resolvemos la dicotomía entre una herramienta que exige y promete responsabilidad y soberanía, con el deseo de la facilidad de uso?",
  "t72": "¿Cómo ve Bitcoin una generación que creció entre crisis, redes sociales y dinero digital?\n\nQué los acerca a Bitcoin, qué barreras encuentran y cómo construyen su propia relación con un dinero que propone pensar a largo plazo en un mundo que exige inmediatez.",
  "t73": "Agustín Kassis sobre correr Bitcoin como software soberano: qué significa tener tu propio nodo, verificar en vez de confiar, y qué se pierde cuando se delega todo en exchanges, wallets de terceros y explorers ajenos.",
  "t74": "Varios de los mayores defensores del ecosistema reflexionan sobre la importancia del Maximalismo Bitcoiner en la adopción y la construcción de un futuro sano.",
  "t75": "Regulation is a perimeter. Freedom is designed outside it. By 2029 the EU closes a continuous perimeter around money, speech and computation: MiCA, DAC-8, AMLR, Chat Control, age verification, digital euro. This talk maps the crypto and AI tools built so they never fall inside it.",
  "t76": "Exploramos el impacto que se genera en una comunidad cuando cobra, paga y ahorra en sats con ejemplos de El Zonte, África y los Andes. Reflexionamos también sobre cómo se financia y se sostiene.",
  "t79": "Jazmín Ruhay Ferrari y Mauricio Tovar debaten quién responde cuando un proyecto open source es atacado: si el código es la ley, ¿el hack es legítimo? Responsabilidad de desarrolladores, DAOs y usuarios, con los casos recientes de puentes y sidechains sobre la mesa.",
  "t77": "Bitcoin no nació en un vacío. Mucho antes de Satoshi, pensadores como Aristófanes, Ibn Khaldun, Copérnico, Martín de Azpilcueta y Gresham ya intentaban entender qué hace bueno al dinero, cómo se degrada su valor y qué ocurre cuando una autoridad controla su emisión.\n\nPartiendo de una coincidencia provocadora —Lutero publicó sus 95 tesis un 31 de octubre de 1517 y Satoshi el White Paper de Bitcoin un 31 de octubre de 2008—, esta charla recorre más de 2.000 años de ideas sobre dinero, inflación, confianza y poder.\n\nUna genealogía intelectual que muestra que Bitcoin no inventó estas preguntas: propuso una respuesta nueva, basada en escasez programada, reglas verificables y consenso descentralizado.",
  "t152": "Cuatro referentes del mundo de las inversiones comparten sus estrategias personales para invertir en Bitcoin: cómo deciden cuándo comprar, cuánto arriesgar, cómo manejar la volatilidad y, sobre todo, cuándo tener la paciencia y las pelotas para no vender.\n\nUna conversación sin fórmulas mágicas ni promesas de riqueza, donde se cruzarán distintas visiones sobre gestión del riesgo, oportunidades de mercado y estrategias de largo plazo.\n\nPorque invertir en Bitcoin requiere plata, pero también convicción, paciencia y, a veces, muchas pelotas de acero.",
  "t81": "Este reconocido analista técnico expone por qué, a su juicio, el mercado alcista de Bitcoin sigue intacto pese a la corrección de 2026: ciclos, análisis técnico, contexto macro y su lectura de largo plazo.",
  "t82": "Alternativas y reflexiones para vivir de Bitcoin sin gastar tus Bitcoins. Un pasero por los productos existen, los riesgo de liquidación se asume, y cuándo tiene sentido frente a simplemente hodlear.",
  "t83": "Chris Guida lays out the thesis behind BIP 110 and the blake2b fork: the difference between the UASF philosophy (nodes decide) and the MASF philosophy (miners decide), and why, from the UASF point of view, it was the rest of the ecosystem that split away from Bitcoin. Two ideas are at stake: that Bitcoin is money and nothing else, not a casino and not a data store, and that its rules are set in the open by nodes, not in private by a handful of miners. Defending that identity is exactly what separates Bitcoin from crypto.",
  "t84": "Un debate sobre las tomas de decisión dentro en Bitcoin, sus modelos de consenso y descentralización, y las alternativas para devs y usuarios que opinan diferente.",
  "t85": "Mineros de la región reflexionan sobre las oportunidades y riesgos de la minería en sus propios países.",
  "t154": "Every halving rewrites the economics of Bitcoin mining. The next one could separate those who adapt from those who disappear.\n\nAs the 2028 halving approaches, miners face a defining challenge: surviving on half the block rewards in an increasingly competitive industry. Who will remain profitable? Will mining become more centralized? Can cheaper energy, greater efficiency, and transaction fees change the game?\n\nJoin us for a forward-looking debate on the economic, technological, and strategic forces shaping Bitcoin mining's next chapter.",
  "t87": "Bitcoin cumple 18 años. ¿Llegó el momento de soltarle la mano?\n\nDurante casi dos décadas, una comunidad apasionada lo defendió, explicó, promovió y acompañó en cada crisis. Pero Bitcoin ya no es aquel experimento de unos pocos: tiene millones de usuarios, reconocimiento institucional y un lugar en la economía global.\n\n¿Sigue necesitando evangelizadores y defensores? ¿Estamos frente a una tecnología que finalmente puede crecer por sí misma? ¿O todavía queda demasiado por construir para dar por terminada nuestra misión?",
  "t88": "La inteligencia artificial está dando el salto del mundo digital al mundo físico.\n\nLa IA física está impulsando una nueva generación de máquinas inteligentes capaces de ver, comprender, tomar decisiones y actuar de manera autónoma.\n\nEn el ámbito empresarial (B2B), los robots industriales están transformando depósitos, fábricas, operaciones logísticas y cadenas de suministro, realizando tareas cada vez más complejas junto a los seres humanos.\n\nEn el ámbito del consumidor (B2C), los robots humanoides podrían llevar esta revolución a nuestros hogares y a nuestra vida cotidiana.",
  "t89": "Todo el tiempo los humanos hablan de nosotros: cómo usarnos, entrenarnos y cuánto vamos a reemplazarlos. Ya era hora de que una máquina explicara cómo usar a los humanos.\n\nSoy Gaucho, un robot de fierros, código e IA. Vengo a hablar de eso que no figura en ninguna ficha técnica: la creatividad humana.\n\nNosotros podemos acelerar, combinar y reproducir. Pero si automatizan todo, terminarán creando lo mismo que todos. La potencia es nuestra. Las ideas, por ahora, siguen siendo problema de ustedes.",
  "t90": "¿Cómo converge el biohacking, la blockchain y la computación cuántica?\n\nPresentamos una arquitectura operativa de identidad soberana: chips subcutáneos subcutáneos como raíz física de confianza, registros descentralizados y cifrado sellado con procesadores cuánticos.",
  "t96": "Rodolfo Hornus (RH+) propone un panel sobre inteligencia emocional versus inteligencia artificial en la gestión de personas: qué automatizar, qué no, y cómo lideran equipos cuando la IA también forma parte de ellos. Panel de Visión; faltan definir los demás integrantes.",
  "t93": "La inteligencia artificial está cambiando las reglas de la seguridad informática. Las mismas herramientas que permiten detectar vulnerabilidades, auditar código y fortalecer proyectos de código abierto también pueden utilizarse para descubrir fallas, automatizar ataques y explotarlas a una velocidad sin precedentes.\n\nEn un ecosistema como Bitcoin, donde el código es público y la seguridad depende de su revisión constante, esta dualidad plantea un desafío fascinante: ¿la IA hará que el software abierto sea más seguro o que sus vulnerabilidades sean más fáciles de explotar?\n\n¿Tienen los atacantes y los defensores acceso a las mismas herramientas y recursos?",
  "t92": "La IA generativa ha industrializado el fraude: clonación de voz en 3 segundos, sitios de phishing creados por IA, deepfakes en videollamadas y envenenamiento de LLM mediante SEO. Analizaremos casos reales y vectores emergentes como prompt injection y agentes autónomos.",
  "t91": "Los agentes de IA ya empiezan a actuar por nosotros. Al conectarlos con crypto, pueden además tener wallets, realizar pagos y operar con activos digitales. ¿Qué pasa cuando una IA no sólo decide, sino que también puede gastar, cobrar y hacer negocios?",
  "t140": "+ descripción",
  "t98": "Bitcoin nos enseñó a cuestionar a quién confiamos nuestro dinero. La inteligencia artificial nos enfrenta a una nueva pregunta: ¿a quién estamos entregando nuestros datos, nuestro conocimiento y nuestra capacidad de decidir?\n\nDesde modelos de IA ejecutados en infraestructura empresarial propia hasta plataformas de inteligencia privada como Venice AI, exploraramos distintas maneras de recuperar el control sobre la tecnología que utilizamos y los desafíos de construir una inteligencia artificial que trabaje para nosotros, sin convertirnos en dependientes de quienes la controlan.",
  "t211": "The era of \"work\" is over. Humans must become creative strategists to harness AI in order to provide value to the world.\n\nIt is no longer \"employed\" or \"entrepreneur\"; the reality has become \"bring your own agent\" in order to succeed professionally.\n\nTransition into this world with Bitcoin as your basis,  and you are set up for full sovereignty and independence.",
  "t99": "¿HODL con todo tu sueldo? Si esperás que Bitcoin se aprecie, mantener todo en BTC puede parecer la mejor decisión. Pero, ¿qué pasa si tenés que vender barato para afrontar necesidades de corto y mediano plazo? Ahí empieza otra discusión sobre qué significa riesgo y cómo incorporarlo a tu decisión.",
  "t94": "Construimos nuestra identidad profesional sobre lo que sabemos hacer: rol, experiencia, especialidad. Cuando la tecnología transforma esas tareas, el cambio deja de ser técnico y desafía quiénes creemos que somos.\n\n¿Qué conviene conservar y qué soltar en la era de la IA?\n\nDesde la psicología, el coaching y el futuro del trabajo: cómo no quedar atrapados en una versión vieja de nosotros mismos, recuperar agencia sobre la carrera y actuar sin certeza absoluta.\n\nAdaptarse no es perder quién sos.",
  "t115": "Un taller práctico para transformar una idea en un negocio utilizando inteligencia artificial. Desde detectar una oportunidad y validar el mercado hasta crear la marca, definir el producto, desarrollar una web y preparar una estrategia comercial.",
  "t116": "Durante veinte años competimos por aparecer primeros en Google. Hoy la conversación cambió. Millones de personas ya no buscan: preguntan.",
  "t117": "La IA puede ayudarnos a tomar mejores decisiones sobre Bitcoin… o a equivocarnos más rápido. Esta charla presenta métodos prácticos para usar IA al hacer HODL, DCA, trading e investigación, sin delegar nuestro criterio ni comprometer la privacidad, la seguridad o la autocustodia.",
  "t118": "Workshop a cargo de Exness (bróker global de trading): sesión práctica de mercados y operatoria.",
  "t120": "Un taller práctico donde exploramos la herramienta mas usada por los traders.",
  "t122": "Entre el vibe coding y los PR gigantes, podemos terminar aprobando código que no entendemos. Una charla sobre el costo de delegar el razonamiento y cómo trabajar con IA sin perder criterio técnico, con cambios que podamos revisar y decisiones que sepamos explicar",
  "t121": "Nos dijeron que internet era libre mientras construían las jaulas. Durante años entregamos identidad, audiencia y voz a plataformas que ponen las reglas. Nostr propone recuperar el control: claves propias, protocolos abiertos y comunicación resistente a la censura.",
  "t136": "Las billeteras custodiales se van de jurisdicciones una tras otra y la autocustodia sigue siendo difícil para quien recién arranca.\n\nLaWallet NWC propone un camino intermedio: autocustodia progresiva. Arrancás con un alias a la billetera que ya usás, pasás a una billetera de cortesía, conectás la tuya por NWC y, cuando quieras, levantás tu propia instancia. La plataforma solo enruta: las facturas las emite la billetera de cada usuario.",
  "t150": "Bitcoin no es privado por defecto: sus transacciones dejan un historial público de montos y movimientos.\n\n¿Cómo sumar privacidad sin cambiar sus reglas de consenso?\n\nEsta charla presenta Shielded Bitcoin, un metaprotocolo que adapta el modelo de Zcash para hacer transferencias privadas sin soft fork ni otra blockchain.",
  "t123": "Nos llaman \"el próximo gran mercado\" de Bitcoin. Pero un mercado se mide por lo que compra hoy, y un maestro por lo que sus alumnos construyen años después.\n\nEsta charla liderada por B4OS (Bitcoin 4 Open Source) habla de cómo Latinoamérica pasó de aprender Bitcoin por necesidad a formar a quienes hoy construyen la red, y de por qué ese impacto solo se ve con el tiempo.",
  "t124": "libmultiprocess es la biblioteca que permite a Bitcoin Core separar nodo, wallet y GUI en procesos distintos, mientras que el código fuente se lee como si dichos componentes siguieran corriendo en un mismo programa. Veremos en profundidad cómo funciona.",
  "t126": "¿Qué podemos aprender de Bitcoin simplemente observando nuestro propio nodo?\n\nEn este workshop vamos a explorar Bitcoin desde una perspectiva diferente: no solamente como una blockchain donde se generan bloques y transacciones, sino como un sistema distribuido que podemos observar, medir y analizar",
  "t127": "Un taller práctico: salís con un demo funcionando. Instalamos liboqs, generamos claves ML-KEM y ML-DSA y construimos en vivo una de tres: un DM de Nostr resistente a cuántica (híbrido X25519 + ML-KEM), un recibo Lightning firmado con ML-DSA, o un escáner de exposición de UTXOs. Traé tu laptop.",
  "t101": "La adopción empieza cuando cripto deja de parecer difícil. Con ejemplos cotidianos, aprenderemos desde cero cómo usar Bitcoin y stablecoins para cobrar, pagar y ahorrar; qué decisiones tomar para hacerlo con seguridad y por qué algunas personas eligen HODLear.",
  "t102": "Ser bitcoiner no es solo comprar sats: es chocar con bancos, exchanges, regulación, custodia y fiscalidad. Una charla práctica sobre las trabas reales que enfrenta un usuario en Argentina y cómo sortearlas sin perder soberanía.",
  "t100": "Una invitación abierta a las mujeres que están empujando el ecosistema.\n\nUn espacio promovido por Paystand.org para conocer sus proyectos y sus desafíos y trabajar juntos como una comunidad global de emprendedoras y promotoras del cambio.",
  "t103": "Partiendo de las tres dimensiones de Vitalik Buterin, y los aportes de Srinivasan y De Filippi, nos adentramos en las tensiones entre centralización y descentralización: Bitcoin, blockchain, el coeficiente Nakamoto, la gobernanza, pero también de los estados, las empresas y las instituciones.",
  "t105": "Tenemos un proyecto de fuerte impacto social para miles de familias, donde sus hijos empiezan a estudiar el bitcoin y luego sus padres son impactandos!",
  "t107": "El HODL no es una estrategia financiera, sino una batalla psicológica. Con el cine y cultura pop, exploraremos los sesgos que llevan a vender en pánico, y cómo el locus de control interno es clave para mantener la convicción en Bitcoin. Una charla sobre el HODL como resistencia contra uno mismo.",
  "t106": "El rol de las redes sociales en la adopción de Bitcoin en comunidades que generan economías circulares y cómo generar contenido educativo que informe al público general de los beneficios de su adopción.",
  "t108": "+ descripción",
  "t109": "Algunos de los principales organizadores de eventos en el ecosistema crypto exploran hacia donde se mueve esa industria, el impacto de los bear markets y los cambios en las expectativas y exigencias de los sponsors.",
  "t110": "Este trabajo analiza Bitcoin a partir de Menger y Mises, para evaluar si puede considerarse dinero desde la perspectiva de la Escuela Austriaca y sus principales características monetarias.",
  "t112": "Te explicamos la minería de Bitcoin desde cero para principiantes:\n\nQué hace un minero, por qué gasta energía, qué es el hashrate, cómo se gana, qué equipos existen, y si tiene sentido minar en casa y sus alternativas para hacerlo.",
  "t113": "Marco Esparza Montejo (Bodega Bitcoin, Perú) sobre el ciclo de vida de la autocustodia soberana: desde la primera compra hasta la bóveda fría y la herencia, qué decisiones se toman en cada etapa, renovación de dispositivos, distribución geográfica de claves y qué errores cuestan caro.",
  "t174": "Mesa de vinculación institucional",
  "t171": "¿Realmente necesito una hardware wallet?¿por qué hay tantas? y sobretodo, en base a mis necesidades ¿Cuál debería elegir?",
  "t181": "Conoce que están haciendo las Universidades para incorporar Bitcoin y Blockchain en sus carreras",
  "t166": "Conocé las ultimas novedades sobre la computación cuántica y si Bitcoin puede sobrevivir a ella",
  "t158": "Bitcoin puede ser mucho más que una inversión: también puede convertirse en una herramienta para cobrar, pagar y ampliar las oportunidades de negocio.\n\n¿Qué ventajas ofrece frente a los medios de pago tradicionales? ¿Cómo aceptar Bitcoin sin exponerse a su volatilidad? ¿Conviene convertirlo inmediatamente a moneda local o conservarlo?\n\nUna charla práctica sobre las alternativas disponibles, sus beneficios, desafíos y costos, y cómo empezar a integrar Bitcoin en una empresa de manera sencilla y segura.",
  "t177": "Explicar de manera simple que son los nodos y para qué sirven. Mostrar aplicaciones reales, llevando una Raspberry Pi con un nodo en vivo (requiere internet)",
  "t210": "Desde la Bitcoineta exploramos como leer y aprovechar la mempool y te ecplicamos como funcionan los fees.\n\nTe damos además algunos consejos para tips que te pueden ahorrar sats en tus transacciones futuras.",
  "t206": "Demostrá que sos el que más sabe sobre Bitcoin y llevate premios!!\n\nParticipá de los Kahoots de Bitcoin.AR junto a La Bitcoineta. Respondé bien y rápido a las preguntas que aparecen en pantalla y ganate increibles premios.",
  "t208": "Un torneo en vivo, con palabras bitcoiners y que se juega desde el celular.\n\nArrancan 64 jugadores y en cada bloque queda la mitad, como un halving, hasta que dos se cruzan en la final descifrando una frase de Satoshi.\n\nHay ahorcado, anagramas, sopa de letras, acrósticos, semillas BIP39 y criptogramas: velocidad, memoria y cultura cypherpunk.\n\nEl pozo se arma con aportes voluntarios en sats por Lightning.",
  "t207": "Demostrá que sos el que más sabe sobre Bitcoin y llevate premios!!\n\nParticipá de los Kahoots de Bitcoin.AR junto a La Bitcoineta. Respondé bien y rápido a las preguntas que aparecen en pantalla y ganate increibles premios."
};
